impl Solution{pub fn number_to_words(mut n:i32)->String{if n==0{return"Zero".into()}fn f(n:i32)->String{let a=["","One","Two","Three","Four","Five","Six","Seven","Eight","Nine","Ten","Eleven","Twelve","Thirteen","Fourteen","Fifteen","Sixteen","Seventeen","Eighteen","Nineteen"];let t=["","","Twenty","Thirty","Forty","Fifty","Sixty","Seventy","Eighty","Ninety"];if n<20{a[n as usize].into()}else if n<100{format!("{}{}",t[(n/10)as usize],if n%10>0{format!(" {}",a[(n%10)as usize])}else{String::new()})}else{format!("{} Hundred{}",a[(n/100)as usize],if n%100>0{format!(" {}",f(n%100))}else{String::new()})}}let s=["","Thousand","Million","Billion"];let mut parts=vec![];let mut i=0;while n>0{if n%1000>0{parts.push(format!("{}{}",f(n%1000),if s[i].is_empty(){String::new()}else{format!(" {}",s[i])}));}n/=1000;i+=1;}parts.reverse();parts.join(" ")}}
